Reet hinny, simple plan:

- Fa each customer compute ti = xi * a + yi * b (the total memory they need).
- Sort customers by ti ascendin'.
- Greedily pick the smallest ti's till the sum exceeds d. That's optimal cos memory only fills and each customer consumes a fixed amount.

Here's a tidy C++ implementashun ye can use:

#include <bits/stdc++.h>
using namespace std;
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n; long long d;
    int a, b;
    if (!(cin >> n >> d)) return 0;
    cin >> a >> b;
    vector<pair<long long,int>> v;
    for (int i = 1; i <= n; ++i) {
        long long x, y; cin >> x >> y;
        long long t = x * 1LL * a + y * 1LL * b;
        v.emplace_back(t, i);
    }
    sort(v.begin(), v.end());
    long long sum = 0;
    vector<int> ans;
    for (auto &p : v) {
        if (sum + p.first <= d) {
            sum += p.first;
            ans.push_back(p.second);
        } else break;
    }
    cout << ans.size() << '\n';
    for (size_t i = 0; i < ans.size(); ++i) {
        if (i) cout << ' ';
        cout << ans[i];
    }
    cout << '\n';
    return 0;
}

